const payload = $input.item.json.body;

const costItems = payload.cost_split || [];
const summary = {
  zeyu:     { name: '哲宇家', owed: 0, paid: 0, remaining: 0, pct: 0 },
  shengmin: { name: '聖閔家', owed: 0, paid: 0, remaining: 0, pct: 0 }
};

for (const item of costItems) {
  summary.zeyu.owed     += parseFloat(item.zeyu_owed     || 0);
  summary.zeyu.paid     += parseFloat(item.zeyu_paid     || 0);
  summary.shengmin.owed += parseFloat(item.shengmin_owed || 0);
  summary.shengmin.paid += parseFloat(item.shengmin_paid || 0);
}

for (const f of Object.values(summary)) {
  f.remaining = Math.round(f.owed - f.paid);
  f.pct = f.owed > 0 ? Math.round(f.paid / f.owed * 1000) / 10 : 0;
}

const locationHash = [...(payload.locations || [])].sort().join('|');

const now = new Date().toLocaleString('zh-TW', {
  timeZone: 'Asia/Taipei',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
});

return [{ json: { ...payload, cost_summary: summary, location_hash: locationHash, last_updated: now } }];

const tripData = $('計算衍生資料').item.json;
const cacheResp = $input.item.json;

let cached = { location_hash: '', ai_content: {} };
let cacheSha = null;

if (cacheResp.sha && cacheResp.content) {
  cacheSha = cacheResp.sha;
  try {
    cached = JSON.parse(Buffer.from(cacheResp.content, 'base64').toString('utf-8'));
  } catch(e) {}
}

const newLocations = (tripData.locations || [])
  .filter(loc => !(loc in (cached.ai_content || {})));

return [{ json: {
  ...tripData,
  cached_ai:     cached.ai_content || {},
  cache_sha:     cacheSha,
  new_locations: newLocations,
  needs_ai:      newLocations.length > 0
} }];

const d = $input.item.json;

// 建立 location → sub_activities 對照表
const locSubs = {};
for (const item of (d.itinerary || [])) {
  const subs = (item.sub_activities || []).filter(s => s.activity);
  if (!subs.length) continue;
  const parts = item.location.replace(/→/g, '-').split('-').map(p => p.trim()).filter(Boolean);
  const key = parts[parts.length - 1] || item.location;
  if (!locSubs[key]) locSubs[key] = [];
  subs.forEach(s => { if (!locSubs[key].includes(s.activity)) locSubs[key].push(s.activity); });
}

// 住宿關鍵字
const ACCOM = /住宿|入住|民宿|飯店|旅館|Hotel|Hostel|Lodge|Motel|Holiday\s*Park|Inn|Resort|Airbnb/i;

// 建立 bookings 摘要（只取住宿相關行）
const bookingLines = (d.bookings || [])
  .filter(b => ACCOM.test(b.name || ''))
  .map(b => `- ${b.name}`)
  .join('\n') || '（無住宿資料）';

const locationBlocks = d.new_locations.map(loc => {
  const subs = locSubs[loc] || [];
  const subLine = subs.length ? `\n  具體行程地點：${subs.join('、')}` : '';
  return `景點：${loc}${subLine}`;
}).join('\n\n');

const prompt = `請用繁體中文為以下旅行地點各寫介紹。
這次旅程的住宿清單（供參考，用於填寫 accommodation 欄位）：
${bookingLines}

以下是需要介紹的地點：
${locationBlocks}

請以 JSON 格式回覆，每個地點的格式如下：
{
  "地點名": {
    "intro": "一句話概述（20字內，結尾加句號）",
    "address": "若為具體景點，填入中文或英文地址；若為廣泛地區則填空字串",
    "area_context": "若為廣泛地區，一句話描述氛圍或特色；若為具體景點則填空字串",
    "accommodation": "若住宿清單中有對應此地點的住宿，填住宿名稱；否則填空字串",
    "trending": ["近期熱門活動或景點1", "近期熱門活動或景點2", "近期熱門活動或景點3"],
    "spot_subtitles": { "具體地點A": "副標（15字內）", "具體地點B": "副標（15字內）" }
  }
}
只回傳 JSON，不要其他說明文字。`;

return [{ json: { ...d, openai_body: {
  model: 'gpt-4o-mini',
  max_tokens: 3000,
  messages: [{ role: 'user', content: prompt }]
} } }];

const tripData = $('比對 hash').item.json;
const openaiResp = $input.item.json;

let newAI = {};
try {
  const rawText = openaiResp.choices[0].message.content.trim();
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) newAI = JSON.parse(match[0]);
} catch(e) {
  console.log('AI parse error:', e.message);
}

return [{ json: {
  ...tripData,
  ai_content:   { ...tripData.cached_ai, ...newAI },
  ai_updated:   true,
  ai_new_count: Object.keys(newAI).length
} }];

const d = $input.item.json;

const dataJson = {
  trip_name:    d.trip_name,
  trip_id:      d.trip_id,
  trip_emoji:   d.trip_emoji  || '✈️',
  trip_status:  d.trip_status || '規劃中',
  date_range:   d.date_range,
  last_updated: d.last_updated,
  locations:    d.locations,
  geo_coords:   d.geo_coords || {},
  itinerary:    d.itinerary || [],
  cost_summary: d.cost_summary,
  cost_split:   d.cost_split || [],
  ai_content:   d.ai_content
};

const cacheJson = {
  location_hash: d.location_hash,
  locations:     d.locations,
  ai_content:    d.ai_content,
  updated_at:    d.last_updated
};

return [{ json: {
  ...d,
  data_json_b64:  Buffer.from(JSON.stringify(dataJson, null, 2)).toString('base64'),
  cache_json_b64: Buffer.from(JSON.stringify(cacheJson, null, 2)).toString('base64')
} }];

const d = $('組合 JSON 檔案').item.json;
const shaResp = $input.item.json;

const putBody = {
  message: `sync(${d.trip_id}): ${d.last_updated}${d.ai_updated ? ' [AI updated ' + d.ai_new_count + ' spots]' : ''}`,
  content: d.data_json_b64,
  ...(shaResp.sha ? { sha: shaResp.sha } : {})
};

return [{ json: { ...d, data_put_body: putBody } }];

const d = $('組合 JSON 檔案').item.json;
const shaResp = $input.item.json;

const putBody = {
  message: `cache(${d.trip_id}): update location hash`,
  content: d.cache_json_b64,
  ...(shaResp.sha ? { sha: shaResp.sha } : {})
};

return [{ json: { ...d, cache_put_body: putBody } }];

const templateResp = $input.item.json;
const tripData = $('組合 JSON 檔案').item.json;
return [{ json: {
  ...tripData,
  index_put_body: {
    message: `init(${tripData.trip_id}): 建立旅程網頁`,
    content: templateResp.content
  }
} }];

const tripData = $('組合 JSON 檔案').item.json;
const tripsResp = $input.item.json;

let trips = [];
let tripsSha = null;

if (tripsResp.sha && tripsResp.content) {
  tripsSha = tripsResp.sha;
  try {
    const parsed = JSON.parse(Buffer.from(tripsResp.content, 'base64').toString('utf-8'));
    trips = parsed.trips || [];
  } catch(e) {}
}

const entry = {
  trip_id:      tripData.trip_id,
  trip_name:    tripData.trip_name,
  emoji:        tripData.trip_emoji || '✈️',
  status:       tripData.trip_status || '規劃中',
  date_range:   tripData.date_range,
  last_updated: tripData.last_updated
};

const idx = trips.findIndex(t => t.trip_id === tripData.trip_id);
if (idx >= 0) {
  trips[idx] = entry;
} else {
  trips.push(entry);
}

const b64 = Buffer.from(JSON.stringify({ trips }, null, 2)).toString('base64');
const putBody = {
  message: `trips: sync ${tripData.trip_id}`,
  content: b64,
  ...(tripsSha ? { sha: tripsSha } : {})
};

return [{ json: { ...tripData, trips_put_body: putBody } }];

